function Remove-LogsAntiguos {
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory)]
        [ValidateScript({ Test-Path $_ -PathType Container })]
        [string]$Ruta,

        [ValidateRange(1, 365)]
        [int]$Dias = 30
    )
    $limite = (Get-Date).AddDays(-$Dias)
    Get-ChildItem $Ruta -File | Where-Object LastWriteTime -lt $limite | ForEach-Object {
        if ($PSCmdlet.ShouldProcess($_.FullName, 'Eliminar')) {
            Remove-Item $_.FullName
        }
    }
}

Remove-LogsAntiguos -Ruta C:\logs -Dias 14 -WhatIf -Verbose

